import { Component, createContext, For, onCleanup, onMount, Show } from "solid-js";

import { InputEngineEventName, type InputEngineEvent } from "#core/ui/input/input-support.js";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { PortraitIcon } from "#core/ui-next/components/portrait-icon.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import {
	VictoriesPopupDataModel,
	VictoriesPopupViewModel,
} from "#base/ui-next/screens/victories/victories-popup-model.jsx";

import style from "#base/ui-next/screens/victories/victories-screen.scss?url";

const VictoriesPopupContext = createContext<VictoriesPopupViewModel>();

export interface VictoriesPopupProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

//#region SCREEN LAYOUT
const VictoriesPopupComponent: Component<VictoriesPopupProps> = (_props) => {
	const model = VictoriesPopupViewModel.get();
	const dataModel = VictoriesPopupDataModel.get();

	dataModel.startTimer();

	onMount(() => {
		window.addEventListener(InputEngineEventName, handleWindowEngineInput);
	});

	onCleanup(() => {
		window.removeEventListener(InputEngineEventName, handleWindowEngineInput);
	});

	const handleWindowEngineInput = (inputEvent: InputEngineEvent) => {
		if (
			inputEvent.isCancelInput() ||
			inputEvent.detail.name == "mousebutton-left" ||
			inputEvent.detail.name == "accept" ||
			inputEvent.detail.name == "touch-tap" ||
			inputEvent.detail.name == "keyboard-enter"
		) {
			dataModel.clickCloseButton();
			inputEvent.preventDefault();
			inputEvent.stopPropagation();
		}
	};

	return (
		<VictoriesPopupContext.Provider value={model}>
			<Panel
				name="Victories-Popup"
				id="victories-popup"
				class={`h-full w-full ${dataModel.extraClass()}`}
			>
				<VSlot class="w-full h-full justify-center">
					<HSlot class="victories-popup-main victories-popup-border w-full bg-no-repeat bg-cover items-center justify-center relative">
						<Show when={!model.victoryUnlockBanner}>
							<PortraitIcon
								playerId={model.players[0].playerId}
								size={32}
							/>
						</Show>
						<VSlot class="relative h-auto items-center">
							<div class="w-full h-9">
								<HSlot class="relative self-center victories-popup-trophy-adjust">
									<div class="filigree-title-accent-left opacity-50" />
									<div class="relative size-16 -mt-12">
										<div
											class="absolute inset-0 bg-no-repeat bg-contain"
											style={{
												"background-image": "url(blp:subsystem_panel_header_icon_backing)",
												filter: "fxs-color-tint(#5b441f)",
											}}
										/>
										<div
											class="absolute inset-0 bg-no-repeat bg-contain"
											style={{ "background-image": "url(blp:pedia_circle_frame)" }}
										/>
										<div
											class="absolute inset-0 bg-no-repeat bg-contain"
											style={{ "background-image": "url(blp:sub_agetimer)" }}
										/>
									</div>
									<div class="filigree-title-accent-right opacity-50 victories-popup-filigree-adjust" />
								</HSlot>
							</div>
							<div class="font-title text-xl text-secondary uppercase">
								<Show
									when={!model.victoryUnlockBanner}
									fallback={<L10n.Compose text="LOC_VICTORIES_POPUP_UNLOCK_TITLE" />}
								>
									<L10n.Compose
										text="LOC_VICTORY_POPUP_COUNTDOWN"
										args={[
											model.players[0].active[0].victoryName,
											model.players[0].turnsToVictory(),
										]}
									/>
								</Show>
							</div>
							<Show when={model.victoryUnlockBanner}>
								<div class="filigree-shell-small h-4 my-2 w-full" />
							</Show>
							<Show
								when={!model.victoryUnlockBanner}
								fallback={
									<div class="mb-4 flex flex-col max-w-192">
										<For each={model.unlockedVictories}>
											{(victory) => (
												<div class="font-title text-lg uppercase mb-2 text-center">
													<L10n.Compose
														text="LOC_VICTORIES_POPUP_UNLOCK_BODY"
														args={[victory.tierName, victory.multiplier]}
													/>
												</div>
											)}
										</For>
										<div class="font-body text-sm">
											<L10n.Compose text="LOC_VICTORIES_POPUP_UNLOCK_FOOTER" />
										</div>
									</div>
								}
							>
								<For each={model.players}>
									{(player, playerIndex) => (
										<For each={player.active}>
											{(victory, victoryIndex) => (
												<Show
													when={
														victory.turnsLeft != -1 &&
														(victoryIndex() == 0 || playerIndex() == 0)
													}
												>
													<L10n.Stylize
														text="LOC_VICTORY_POPUP_DETAIL"
														args={[
															player.playerName,
															victory.victoryName,
															victory.turnsLeft,
														]}
													/>
													<Show when={playerIndex() == 0}>
														<div class="mb-4" />
													</Show>
												</Show>
											)}
										</For>
									)}
								</For>
							</Show>
						</VSlot>
						<Show when={!model.victoryUnlockBanner}>
							<div class="size-32" />
						</Show>
					</HSlot>
				</VSlot>
			</Panel>
		</VictoriesPopupContext.Provider>
	);
};

//#endregion

export const VictoriesPopup = ComponentRegistry.register({
	name: "VictoriesPopup",
	styles: [style],
	createInstance: VictoriesPopupComponent,
});

defineLegacyComponent("screen-victories-popup", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return <VictoriesPopup />;
});
